-- Korean text for the place screen (GET /api/places/{id}?lang=ko). Names and addresses stay English.
-- Run once in the Supabase SQL editor. Safe to run again.
alter table places add column if not exists description_ko text;
alter table places add column if not exists signature_menu_ko text;
begin;
update places set description_ko = $ko$인트라무로스에 있는 공예품·기념품 가게예요. 섬세한 3D 페이퍼 아트로 잘 알려져 있어요.$ko$, signature_menu_ko = null where place_id = 'MNL-0001';
